// Real public sequence used by the hero helix. Fetched from NCBI RefSeq on 2026-10-02.
// The record is annotated for Solanum tuberosum; it is not claimed as Criolla Colombia data.
export const sp6a = {
	gene: 'StSP6A (FT)',
	product: { es: 'proteína FLOWERING LOCUS T', en: 'FLOWERING LOCUS T protein' },
	organism: 'Solanum tuberosum',
	accession: 'NM_001287968.1',
	url: 'https://www.ncbi.nlm.nih.gov/nuccore/NM_001287968.1',
	sequence:
		''
} as const

const pairs: Record<string, string> = { A: 'T', T: 'A', G: 'C', C: 'G' }

export function complement(base: string): string {
	return pairs[base] ?? 'N'
}
